async (page) => {
  const fs = require('fs');
  const path = require('path');

  const broken = [];

  function walk(dir) {
    let entries;
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch (e) {
      return;
    }
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (entry.isSymbolicLink()) {
        try {
          fs.statSync(full); // follows symlink
        } catch (e) {
          broken.push(full);
        }
      } else if (entry.isDirectory()) {
        walk(full);
      }
    }
  }

  // Try both possible workspace roots
  const roots = ['/workspace', '/tmp/mcp-workspace', '/tmp/mcp-workspace/workspace'];
  const results = {};
  for (const r of roots) {
    if (fs.existsSync(r)) {
      const before = broken.length;
      walk(r);
      results[r] = broken.slice(before);
    } else {
      results[r] = 'NOT FOUND';
    }
  }
  return JSON.stringify(results, null, 2);
}

